// A complex number as a point, with its modulus and its argument.
//
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(300,300);
usepackage("amsmath");
pair O=(0,0);
pair z=(3,4);
draw((-4.4,0)--(4.4,0),Arrow);
draw((0,-4.4)--(0,4.4),Arrow);
label("$\operatorname{Re}$",(4.5,0),E);
label("$\operatorname{Im}$",(0,4.5),N);
label("$1$",(1,0),S);
label("$i$",(0,1),E);
draw(O--z);
label("$|z|$",(1.5,2.0),NW);
label("$\theta=\arg z$",(2.1,0.6),E);
dot(z, black+3pt);
label("$z$",z,NE);
dot((3,0), black+2.5pt);
label("$\operatorname{Re} z$",(3,-0.35),S);

// A parabola translated up and then reflected in the x-axis.
//
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
import graph;
size(300,300);
draw(graph(new real(real t){return t*t-3;},-1.8,1.8),gray+dashed);
draw(graph(new real(real t){return 3-t*t;},-1.8,1.8));
draw((-2.2,0)--(2.2,0));
draw((0,-4.2)--(0,4.2));
label("$x$",(2.3,0),E);
label("$y$",(0,4.3),N);
dot((0,3), black+2.5pt);
label("$(0,3)$",(0.2,3.2),NW);
dot((0,-3), black+3pt);
label("$(0,-3)$",(0.2,-3.3),NE);
